function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };
  const O = '#051428', Blue = '#335d92', BlueLt = '#5c8dc5', BlueDk = '#163357';
  const Cyan = '#38bdf8', White = '#f5f7fa', Gold = '#f4c020';

  // soft glow ring (hard pixels)
  px(22, 22, 20, 20, BlueDk);
  px(24, 20, 16, 24, BlueDk);
  px(20, 24, 24, 16, BlueDk);

  // core diamond / spark
  px(28, 18, 8, 28, O);
  px(18, 28, 28, 8, O);
  px(29, 19, 6, 26, Blue);
  px(19, 29, 26, 6, Blue);
  px(30, 22, 4, 20, BlueLt);
  px(22, 30, 20, 4, BlueLt);
  px(31, 26, 2, 12, Cyan);
  px(26, 31, 12, 2, Cyan);
  // hot center
  px(30, 30, 4, 4, White);
  px(31, 31, 2, 2, Gold);
  // bit ticks
  px(14, 30, 3, 4, Cyan);
  px(47, 30, 3, 4, Cyan);
  px(30, 14, 4, 3, Cyan);
  px(30, 47, 4, 3, Cyan);
}
